static void z_t3618_set(z_t3618_t* _this, z_t52_t _key, uint32_t _val);
static void z_t3618_set(z_t3618_t* _this, z_t52_t _key, uint32_t _val) {
    uint64_t h = z_t3618_hash_key(&_key);
    int64_t existing = z_t3618_find(_this, &_key, h, NULL);
    if (existing >= 0) {
        _this->entries[existing].value = _val;
        z_t52_free(&_key);
        return;
    }
    if (_this->capacity == 0 || (_this->entries_len + 1) * 3 >= _this->capacity * 2) {
        z_t3618_grow(_this);
    }
    uint64_t probe = h & (_this->capacity - 1);
    int64_t first_deleted = -1;
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T3618_INDEX_EMPTY) {
            if (first_deleted >= 0) probe = (uint64_t)first_deleted;
            break;
        }
        if (slot == Z_T3618_INDEX_DELETED && first_deleted < 0) {
            first_deleted = (int64_t)probe;
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    if (_this->entries_len >= _this->entries_cap) {
        uint64_t new_ec = _this->entries_cap == 0 ? 8 : _this->entries_cap * 2;
        _this->entries = (z_t3618_entry_t*)z_xrealloc(_this->entries, new_ec * sizeof(z_t3618_entry_t));
        for (uint64_t i = _this->entries_cap; i < new_ec; i++) {
            _this->entries[i] = (z_t3618_entry_t){0};
        }
        _this->entries_cap = new_ec;
    }
    int64_t new_idx = (int64_t)_this->entries_len;
    _this->entries[new_idx].alive = 1;
    _this->entries[new_idx].hash = h;
    _this->entries[new_idx].key = _key;
    _this->entries[new_idx].value = _val;
    _this->entries_len++;
    _this->indices[probe] = new_idx;
    _this->length++;
}

static z_t356_t z_t3618_get(z_t3618_t* _this, const z_t52_t* _key);
static z_t356_t z_t3618_get(z_t3618_t* _this, const z_t52_t* _key) {
    uint64_t h = z_t3618_hash_key(_key);
    int64_t idx = z_t3618_find(_this, _key, h, NULL);
    z_t356_t _r;
    if (idx >= 0) {
        _r.tag = Z_OPTIONVAL_U32_TAG_SOME;
        _r.data.some = _this->entries[idx].value;
    } else {
        _r.tag = Z_OPTIONVAL_U32_TAG_NONE;
    }
    return _r;
}

static z_t356_t z_t3618_remove(z_t3618_t* _this, const z_t52_t* _key);
static z_t356_t z_t3618_remove(z_t3618_t* _this, const z_t52_t* _key) {
    uint64_t h = z_t3618_hash_key(_key);
    int64_t slot = -1;
    int64_t idx = z_t3618_find(_this, _key, h, &slot);
    z_t356_t _r;
    if (idx < 0) {
        _r.tag = Z_OPTIONVAL_U32_TAG_NONE;
        return _r;
    }
    _r.tag = Z_OPTIONVAL_U32_TAG_SOME;
    _r.data.some = _this->entries[idx].value;
    z_t52_free(&_this->entries[idx].key);
    _this->entries[idx].alive = 0;
    _this->indices[slot] = Z_T3618_INDEX_DELETED;
    _this->length--;
    return _r;
}

